import{_ as i,o as n,c as u,a2 as t}from"./chunks/framework.CqpfiAoK.js";const l=JSON.parse('{"title":"Muundo na Viwango vya Neo","description":"","frontmatter":{},"headers":[],"relativePath":"sw/20-锚点结构与层级.md","filePath":"sw/20-锚点结构与层级.md","lastUpdated":null}'),o={name:"sw/20-锚点结构与层级.md"};function e(h,a,w,k,s,d){return n(),u("div",null,[...a[0]||(a[0]=[t('<h1 id="muundo-na-viwango-vya-neo" tabindex="-1">Muundo na Viwango vya Neo <a class="header-anchor" href="#muundo-na-viwango-vya-neo" aria-label="Permalink to &quot;Muundo na Viwango vya Neo&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Mradi</th><th>Maudhui</th></tr></thead><tbody><tr><td>Nambari ya Hati</td><td>20</td></tr><tr><td>Moduli</td><td>Mfumo wa Neo na Kanuni za Usawa</td></tr><tr><td>Maneno Muhimu</td><td>Muundo wa Neo, Mfumo wa Viwango, Mtandao wa Sheria, Uunganisho wa Viwango, Kiini cha Uwezo wa Kuzingatia</td></tr></tbody></table><h2 id="_1-ufafanuzi-wa-asili-wa-neo" tabindex="-1">1. Ufafanuzi wa Asili wa Neo <a class="header-anchor" href="#_1-ufafanuzi-wa-asili-wa-neo" aria-label="Permalink to &quot;1. Ufafanuzi wa Asili wa Neo&quot;">​</a></h2><p>Neo ni mfumo wa msingi katika Heng Yuan Zhou unaodumisha usawa wa ulimwengu, kudhibiti mtiririko wa nishati, na kusaidia mtandao wa usawa. Kwa asili, neo sio tu nodi ya kimwili au hatua ya mkusanyiko wa nishati, bali ni &quot;tukio la kudumu&quot; la sheria za asili za ulimwengu kwenye mawasiliano ya nafasi-na-muda mahususi — inabadilisha sheria za kiufundi kuwa muundo wa kimwili unaoweza kuchambuliwa, kudhibitiwa, na kutunzwa, ili nishati za kibinafsi zilizotawanyika ziweze kufikia mkusanyiko na kushiriki kupitia mtandao wenye utaratibu.</p><p>Kazi za msingi za neo zinaweza kufupishwa katika mazingira matatu:</p><ol><li><strong>Uwezo wa Kuzingatia Sheria</strong>: Kufanya thamani za utendaji wa sheria za asili za ulimwengu kudumu kwenye nodi mahususi, kuzuia usawa wa ulimwengu unaosababishwa na uharibifu wa sheria</li><li><strong>Kituo cha Nishati</strong>: Kufanya kazi kama nodi ya kupitia kwa ajili ya mkusanyiko, ubadilishaji, na mgawanyo wa nishati, na kutekeleza usimamizi wa nishati kati ya viwango na kati ya mazingira</li><li><strong>Kiolesura cha Usawa</strong>: Kutoa kiolesura cha kiwango cha usawa kwa ajili ya maisha ya kibinafsi kuingia kwenye mtandao wa usawa, ili matokeo ya kila mtu anayefanya uozi ziweze kuingia kwenye mkondo wa mageuzi ya pamoja</li></ol><p>Tofauti na nodi za rasilimali kama vile &quot;mishipa ya roho&quot; na &quot;maeneo ya mbingu&quot; katika mfumo wa uwindaji, neo haina mwenyewe wa kibinafsi wa mtu yeyote au shirika, bali ni miundombinu ya umma ya maisha yote ya usawa ya Heng Yuan Zhou. Tabia yoyote ya umiliki wa kibinafsi wa neo inakataa kanuni za msingi za Katiba ya Usawa.</p><h2 id="_2-muundo-wa-viwango-tano-vya-neo" tabindex="-1">2. Muundo wa Viwango Tano vya Neo <a class="header-anchor" href="#_2-muundo-wa-viwango-tano-vya-neo" aria-label="Permalink to &quot;2. Muundo wa Viwango Tano vya Neo&quot;">​</a></h2><p>Mfumo wa neo katika Heng Yuan Zhou umegawanywa katika viwango vitano kulingana na upeo wa funiko, kina cha sheria, na uwezo wa nishati. Kati ya viwango kila moja kuna muundo wa toposhia wa mti: neo cha kiwango cha juu huchukua usimamizi wa neo cha kiwango cha chini, na neo cha kiwango cha chini hukusanya nishati na taarifa kwenda juu, na kuunda mzunguko kamili wa &quot;kupitia chini na kukusanya juu&quot;.</p><table tabindex="0"><thead><tr><th>Kiwango</th><th>Jina</th><th>Kiwango cha Idadi</th><th>Upeo wa Funiko</th><th>Kazi ya Msingi</th><th>Kina cha Sheria</th></tr></thead><tbody><tr><td>Kiwango cha 1</td><td>Neo cha Asili cha Ulimwengu</td><td>1 kitu</td><td>Heng Yuan Zhou nzima</td><td>Kudumisha utulivu wa sheria za msingi za ulimwengu, kuchukua usimamizi wa mtandao wote wa neo</td><td>Safu ya Asili</td></tr><tr><td>Kiwango cha 2</td><td>Neo cha Kiini cha Ulimwengu</td><td>1-3 kila upeo</td><td>Upeo mmoja wa upeo</td><td>Kudumisha utulivu wa sheria za upeo, kudhibiti mtiririko wa nishati cha kiwango cha upeo</td><td>Safu ya Sheria</td></tr><tr><td>Kiwango cha 3</td><td>Neo cha Kituo cha Eneo la Nyota</td><td>Makumi kila eneo la nyota</td><td>Upeo wa kiwango cha eneo la nyota</td><td>Kuunganisha neo cha kiwango cha galaksi, kuchukua jukumu la kupitia nishati za eneo</td><td>Safu ya Nusu-Sheria</td></tr><tr><td>Kiwango cha 4</td><td>Neo cha Nodi ya Galaksi</td><td>Mamia kila galaksi</td><td>Upeo wa kiwango cha galaksi</td><td>Kuunganisha neo cha kiwango cha sayari, kutoa ufikiaji wa mtandao wa usawa wa eneo</td><td>Safu ya Nishati</td></tr><tr><td>Kiwango cha 5</td><td>Neo cha Ufikiaji wa Sayari</td><td>Maelfu kila sayari</td><td>Uso wa sayari na orbiti ya karibu</td><td>Kutoa kiolesura cha ufikiaji wa moja kwa moja kwa maisha ya kibinafsi</td><td>Safu ya Vifaa</td></tr></tbody></table><p>Uunganisho kati ya neo za viwango vitano sio uhusiano wa juu-chini wa kawaida, bali unafuata kanuni ya &quot;chelezo cha ziada, usambazaji wa nguvu&quot;. Kila neo cha kiwango cha chini inaunganishwa kwa wakati huo huo na angalau neo mbili za kiwango cha juu; wakati njia moja inakutana na kasoro, nishati na taarifa zinaweza kubadilisha moja kwa moja hadi njia ya chelezo, na kuhakikisha upatikanaji wa juu wa mtandao wote.</p><h2 id="_3-muundo-wa-ndani-wa-neo" tabindex="-1">3. Muundo wa Ndani wa Neo <a class="header-anchor" href="#_3-muundo-wa-ndani-wa-neo" aria-label="Permalink to &quot;3. Muundo wa Ndani wa Neo&quot;">​</a></h2><p>Kila neo, bila kujali kiwango chake cha juu au chini, inafuata usanifu wa &quot;miiba mitatu na pete mbili&quot; katika muundo wake wa ndani, na usanifu huu ni msingi wa utendaji thabiti wa neo:</p><h3 id="_3-1-muundo-wa-miiba-mitatu" tabindex="-1">3.1 Muundo wa Miiba Mitatu <a class="header-anchor" href="#_3-1-muundo-wa-miiba-mitatu" aria-label="Permalink to &quot;3.1 Muundo wa Miiba Mitatu&quot;">​</a></h3><ol><li><strong>Kiini cha Sheria</strong>: Kiini cha neo, kinachohifadhi thamani za sheria za asili zinazozingatiwa na neo hii. Utulivu wa kiini cha sheria unamamishi moja kwa moja ubora wa utendaji wa neo; mara kiini cha sheria kinapopata mshtuko, neo nzima itakutana na uharibifu wa sheria hata uangamivu</li><li><strong>Kiini cha Nishati</strong>: Inawajibika kwa kupokea, kuhifadhi, kubadilisha, na kutoa nishati. Kiini cha nishati kina uwezo wa kulingana na nishati za aina nyingi, na kunaweza kushughulikia kwa wakati huo huo nishati ya vifaa, nishati ya roho, nishati ya ufahamu, na aina nyingine</li><li><strong>Kiini cha Taarifa</strong>: Inawajibika kwa usindikaji wa taarifa za mtandao wa usawa, ikiwa ni pamoja na kukusanya majibu ya uozi, kutuma maagizo ya uboreshaji wa mfumo, kufuatilia hali ya kibinafsi, n.k. Kiini cha taarifa ni ufunguo wa neo kufikia &quot;usimamizi wa akili&quot;</li></ol><h3 id="_3-2-muundo-wa-pete-mbili" tabindex="-1">3.2 Muundo wa Pete Mbili <a class="header-anchor" href="#_3-2-muundo-wa-pete-mbili" aria-label="Permalink to &quot;3.2 Muundo wa Pete Mbili&quot;">​</a></h3><ol><li><strong>Pete ya Ulinzi</strong>: Muundo wa ulinzi wa safu ya nje unaofunga miiba mitatu, na ina uwezo wa ulinzi wa mara tatu: ulinzi wa kimwili, ulinzi wa nishati, na ulinzi wa ufahamu, na kuzuia neo kupata shambulio la nje au uharibifu wa kisikizo</li><li><strong>Pete ya Ukadiriaji</strong>: Iko kati ya pete ya ulinzi na miiba mitatu, na inawajibika kwa ukadiriaji wa muda mrefu wa thamani za utendaji wa miiba mitatu, na kuhakikisha kuwa kiini cha sheria hakiharibiki, kiini cha nishati hakijitokeza, na kiini cha taarifa hakichanganyiki</li></ol><h2 id="_4-mchakato-wa-ujenzi-na-uanzishaji-wa-neo" tabindex="-1">4. Mchakato wa Ujenzi na Uanzishaji wa Neo <a class="header-anchor" href="#_4-mchakato-wa-ujenzi-na-uanzishaji-wa-neo" aria-label="Permalink to &quot;4. Mchakato wa Ujenzi na Uanzishaji wa Neo&quot;">​</a></h2><p>Ujenzi wa neo ni mradi wa mfumo, na inahitaji kupitia hatua tano za uteuzi wa eneo, kuweka msingi, kuanzisha, ukadiriaji, na kuingia kwenye mtandao:</p><ol><li><strong>Hatua ya Uteuzi wa Eneo</strong>: Kupitia mfumo wa usimamizi wa sheria ya nafasi, kuchunguza viashiria kama vile uzito wa sheria, utulivu wa nishati, na uhai wa jiolojia kwenye mawasiliano ya mgombea, na kuchagua nodi zinazofikia masharti ya ujenzi</li><li><strong>Hatua ya Kuweka Msingi</strong>: Kuweka mbegu ya kiini cha neo kwenye mawasiliano yaliyochaguliwa, na kuchambua nishati ya awali ili kiini cha sheria kianze kuimarika. Hatua hii kwa kawaida inahitaji ingizo la nishati cha kiwango cha Mtu Mwenye Nguvu zaidi cha Kiwangazi</li><li><strong>Hatua ya Kuanzisha</strong>: Wakati uimarishaji wa kiini cha sheria umekamilika, kuanzisha kiini cha nishati na kiini cha taarifa kupitia ibada mahususi au njia za teknolojia, na kutoa neo uwezo wa msingi wa utendaji</li><li><strong>Hatua ya Ukadiriaji</strong>: Neo iliyoanzishwa inahitaji kupitia ukadiriaji wa muda mrefu wa angalau mzunguko wa kiwango cha kawaida, na kuhakikisha kuwa thamani zote ziko thabiti ndani ya upeo unaoruhusiwa</li><li><strong>Hatua ya Kuingia kwenye Mtandao</strong>: Neo iliyokamilika ukadiriaji inaingia rasmi kwenye mtandao wa usawa, na kuanza kuchukua jukumu la kupitia nishati na usindikaji wa taarifa</li></ol><h2 id="hitimisho" tabindex="-1">Hitimisho <a class="header-anchor" href="#hitimisho" aria-label="Permalink to &quot;Hitimisho&quot;">​</a></h2><p>Muundo na mfumo wa viwango vya neo ni mfupa wa miundombinu ya utamaduni wa usawa wa Heng Yuan Zhou. Kuelewa viwango vitano vya neo na muundo wa ndani wa &quot;miiba mitatu na pete mbili&quot; ni utangulizi wa kuelewa kanuni za utendaji wa mtandao wote wa usawa. Pamoja na maendeleo ya uchunguzi wa kati ya mazingira, mfumo wa neo unaendelea kupanuka, na mwishowe utafunika kila kona ya Heng Yuan Zhou.</p><h2 id="hati-zinazohusiana" tabindex="-1">Hati zinazohusiana <a class="header-anchor" href="#hati-zinazohusiana" aria-label="Permalink to &quot;Hati zinazohusiana&quot;">​</a></h2><ul><li>21-共生网络运作原理 (Kanuni za Utendaji wa Mtandao wa Usawa)</li><li>24-锚点能量传导路径 (Njia ya Mabadilisho ya Nishati ya Neo)</li><li>27-锚点校准与维护 (Ukadiriaji na Matunzaji ya Neo)</li></ul>',24)])])}const r=i(o,[["render",e]]);export{l as __pageData,r as default};
